*, *::before, *::after { box-sizing: border-box; }

.shell {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-areas:
    "header header"
    "sidebar main";
  min-height: 100vh;
}
.header { grid-area: header; display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.sidebar { grid-area: sidebar; }
.main { grid-area: main; }

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

.row { display: flex; width: 600px; gap: 20px; }
.sidebar { flex: 0 1 200px; }
.content { flex: 1 1 200px; }
.ads { flex: 1 1 100px; }

