practice.solution:
const lines = stdin.trim().split('\n');
const [width, gap] = lines[0].trim().split(/\s+/).map(Number);
const items = lines.slice(1).map(l => {
  const [name, basis, grow, shrink] = l.split('|');
  return { name: name.trim(), basis: +basis, grow: +grow, shrink: +shrink };
});
const fmt = x => String(Number(x.toFixed(2)));
const free = width - items.reduce((s, it) => s + it.basis, 0) - gap * (items.length - 1);
console.log('Free space: ' + fmt(free));
const totalGrow = items.reduce((s, it) => s + it.grow, 0);
const totalScaled = items.reduce((s, it) => s + it.shrink * it.basis, 0);
for (const it of items) {
  let w = it.basis;
  if (free >= 0 && totalGrow > 0) w += free * it.grow / totalGrow;
  if (free < 0 && totalScaled > 0) w += free * (it.shrink * it.basis) / totalScaled;
  console.log(`${it.name}: ${fmt(w)}`);
}
